import{_ as e,o as i,c as t,ae as n}from"./chunks/framework.Bwt6MOeu.js";const p=JSON.parse('{"title":"Academy Interaction Contract","description":"","frontmatter":{},"headers":[],"relativePath":"guide/academy-interaction-contract.md","filePath":"guide/academy-interaction-contract.md"}'),r={name:"guide/academy-interaction-contract.md"};function o(l,a,s,d,c,u){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="academy-interaction-contract" tabindex="-1">Academy Interaction Contract <a class="header-anchor" href="#academy-interaction-contract" aria-label="Permalink to &quot;Academy Interaction Contract&quot;">​</a></h1><p>This document defines the allowed interaction model for Academy participants, mentors, guardians, and platform operators.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>Educational systems fail when interaction boundaries are implied but not encoded. Academy uses an explicit interaction contract so that role boundaries, reviewability, and safeguarding expectations are clear.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>The main interaction roles are:</p><ul><li>learner</li><li>mentor</li><li>guardian</li><li>operator / safeguarding reviewer</li><li>organization / provider representative</li></ul><h2 id="interaction-design-goals" tabindex="-1">Interaction design goals <a class="header-anchor" href="#interaction-design-goals" aria-label="Permalink to &quot;Interaction design goals&quot;">​</a></h2><p>The interaction model is designed to:</p><ul><li>reduce private, opaque, and unsafe communication patterns</li><li>keep learning pathways usable</li><li>preserve attributable records</li><li>support guardian-linked participation where appropriate</li><li>enable escalation and review</li></ul><h2 id="adult-and-minor-interactions" tabindex="-1">Adult and minor interactions <a class="header-anchor" href="#adult-and-minor-interactions" aria-label="Permalink to &quot;Adult and minor interactions&quot;">​</a></h2><p>Adult-to-minor interactions must be bounded by the documented safeguarding model. Academy does not treat unrestricted private adult-to-minor communication as a normal operating mode.</p><p>Where minor participation exists, the contract must favor:</p><ul><li>structured sessions</li><li>attributable records</li><li>guardian-aware or safeguarded pathways</li><li>documented reviewability</li></ul><h2 id="learner-interactions" tabindex="-1">Learner interactions <a class="header-anchor" href="#learner-interactions" aria-label="Permalink to &quot;Learner interactions&quot;">​</a></h2><p>Learner-to-learner interaction may be permitted within documented boundaries, but it is still subject to platform policy, escalation rules, and safety review.</p><h2 id="guardian-linked-pathways" tabindex="-1">Guardian-linked pathways <a class="header-anchor" href="#guardian-linked-pathways" aria-label="Permalink to &quot;Guardian-linked pathways&quot;">​</a></h2><p>Where policy requires it, guardians are linked into visibility, approval, or oversight pathways. Guardian-linked pathways must be explicit rather than informal.</p><h2 id="reviewability" tabindex="-1">Reviewability <a class="header-anchor" href="#reviewability" aria-label="Permalink to &quot;Reviewability&quot;">​</a></h2><p>Important interaction pathways must be:</p><ul><li>attributable</li><li>bounded by role</li><li>reviewable when policy requires it</li><li>supportable in escalation workflows</li></ul><h2 id="sensitive-situations" tabindex="-1">Sensitive situations <a class="header-anchor" href="#sensitive-situations" aria-label="Permalink to &quot;Sensitive situations&quot;">​</a></h2><p>The interaction contract must not force all reports into ordinary visibility patterns. Sensitive safeguarding scenarios require special handling and documented escalation logic.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>The interaction contract is meaningful only if product and operations actually enforce it. This includes:</p><ul><li>role-bounded interactions</li><li>controlled communication paths</li><li>auditability</li><li>escalation support</li><li>policy-linked handling</li></ul><h2 id="related-documents" tabindex="-1">Related documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related documents&quot;">​</a></h2><ul><li>Academy Safeguarding and Minor Protection</li><li>Guardian Rights, Sensitive Reports, and Escalation</li><li>Privacy</li><li>Terms</li></ul>',28)])])}const m=e(r,[["render",o]]);export{p as __pageData,m as default};
